begin;
select no_plan();
insert into auth.users (id,email) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','update-a@example.com'), ('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','update-b@example.com');
insert into public.cards (id,user_id,name,bank,network,last4,credit_limit,cutoff_day,payment_day,purchase_rate_ea,advance_fee)
values ('aaaaaaaa-0000-4000-8000-000000000001','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','Visa','Banco','Visa','1234',1000000,15,5,0.28,15000);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa","role":"authenticated"}',true);
select public.create_transaction_with_installments('{"card_id":"aaaaaaaa-0000-4000-8000-000000000001","type":"purchase","date":"2026-01-14","amount":"6000","currency":"COP","fx_rate":null,"amount_cop":"6000","installments_count":1,"interest_free":false,"rate_ea_applied":"0.28","category_id":null,"merchant":"Prueba edición","note":"","installments":[]}'::jsonb);
update public.cards set purchase_rate_ea=0.40 where id='aaaaaaaa-0000-4000-8000-000000000001';
select lives_ok($sql$select public.update_transaction_with_installments((select id from public.transactions where merchant='Prueba edición'), '{"card_id":"aaaaaaaa-0000-4000-8000-000000000001","type":"purchase","date":"2026-01-16","amount":"6000","currency":"COP","fx_rate":null,"amount_cop":"6000","installments_count":2,"interest_free":true,"rate_ea_applied":"0.28","category_id":null,"merchant":"Editado","note":"","installments":[{"number":1,"cutoff_date":"2026-02-15","principal":"3000","interest":"0","total":"3000","balance_after":"3000","principal_cop":"3000","interest_cop":"0","total_cop":"3000"},{"number":2,"cutoff_date":"2026-03-15","principal":"3000","interest":"0","total":"3000","balance_after":"0","principal_cop":"3000","interest_cop":"0","total_cop":"3000"}]}'::jsonb)$sql$, 'edita y regenera cuotas con tasa original');
select is((select count(*) from public.installments),2::bigint,'dos cuotas');
select is((select rate_ea_applied from public.transactions where merchant='Editado'),0.28::numeric,'conserva tasa original');
select is((select s.cutoff_date from public.transactions t join public.statements s on s.id=t.statement_id where t.merchant='Editado'),'2026-02-15'::date,'fecha posterior al corte');
select throws_ok($sql$select public.update_transaction_with_installments((select id from public.transactions where merchant='Editado'), '{"card_id":"aaaaaaaa-0000-4000-8000-000000000001","type":"purchase","date":"2026-01-16","amount":"6000","currency":"COP","fx_rate":null,"amount_cop":"6000","installments_count":1,"interest_free":false,"rate_ea_applied":"0.40","category_id":null,"merchant":"Cambio inválido","note":"","installments":[]}'::jsonb)$sql$, '22023', null, 'rechaza cambio de tasa congelada');
select is((select count(*) from public.installments),2::bigint,'el error conserva las cuotas originales');
select public.create_transaction_with_installments('{"card_id":"aaaaaaaa-0000-4000-8000-000000000001","type":"cash_advance","date":"2026-01-16","amount":"1000","currency":"COP","fx_rate":null,"amount_cop":"1000","installments_count":1,"interest_free":false,"rate_ea_applied":"0","category_id":null,"merchant":"Avance","note":"","installments":[]}'::jsonb);
select is((select count(*) from public.transactions where type='advance_fee'),1::bigint,'el avance tiene comisión');
select lives_ok($sql$select public.update_transaction_with_installments((select id from public.transactions where merchant='Avance'), '{"card_id":"aaaaaaaa-0000-4000-8000-000000000001","type":"purchase","date":"2026-01-16","amount":"1000","currency":"COP","fx_rate":null,"amount_cop":"1000","installments_count":1,"interest_free":false,"rate_ea_applied":"0.40","category_id":null,"merchant":"Antes avance","note":"","installments":[]}'::jsonb)$sql$, 'convierte avance en compra');
select is((select count(*) from public.transactions where type='advance_fee'),0::bigint,'al cambiar tipo se elimina la comisión');
select is((select rate_ea_applied from public.transactions where merchant='Antes avance'),0.40::numeric,'tipo nuevo usa tasa vigente');
select public.create_transaction_with_installments('{"card_id":"aaaaaaaa-0000-4000-8000-000000000001","type":"purchase","date":"2026-01-16","amount":"3","currency":"USD","fx_rate":"4000","amount_cop":"12000","installments_count":3,"interest_free":true,"rate_ea_applied":"0.40","category_id":null,"merchant":"USD edición","note":"","installments":[{"number":1,"cutoff_date":"2026-02-15","principal":"1","interest":"0","total":"1","balance_after":"2","principal_cop":"4000","interest_cop":"0","total_cop":"4000"},{"number":2,"cutoff_date":"2026-03-15","principal":"1","interest":"0","total":"1","balance_after":"1","principal_cop":"4000","interest_cop":"0","total_cop":"4000"},{"number":3,"cutoff_date":"2026-04-15","principal":"1","interest":"0","total":"1","balance_after":"0","principal_cop":"4000","interest_cop":"0","total_cop":"4000"}]}'::jsonb);
select lives_ok($sql$select public.update_transaction_with_installments((select id from public.transactions where merchant='USD edición'), '{"card_id":"aaaaaaaa-0000-4000-8000-000000000001","type":"purchase","date":"2026-01-16","amount":"3","currency":"USD","fx_rate":"4500","amount_cop":"13500","installments_count":3,"interest_free":true,"rate_ea_applied":"0.40","category_id":null,"merchant":"USD edición","note":"","installments":[{"number":1,"cutoff_date":"2026-02-15","principal":"1","interest":"0","total":"1","balance_after":"2","principal_cop":"4500","interest_cop":"0","total_cop":"4500"},{"number":2,"cutoff_date":"2026-03-15","principal":"1","interest":"0","total":"1","balance_after":"1","principal_cop":"4500","interest_cop":"0","total_cop":"4500"},{"number":3,"cutoff_date":"2026-04-15","principal":"1","interest":"0","total":"1","balance_after":"0","principal_cop":"4500","interest_cop":"0","total_cop":"4500"}]}'::jsonb)$sql$, 'actualiza TRM y equivalentes COP');
select is((select sum(i.principal) from public.installments i join public.transactions t on t.id=i.transaction_id where t.merchant='USD edición'),3::numeric,'capital USD no cambia');
select is((select sum(i.principal_cop) from public.installments i join public.transactions t on t.id=i.transaction_id where t.merchant='USD edición'),13500::numeric,'capital COP usa nueva TRM');
select public.create_transaction_with_installments(jsonb_build_object('card_id','aaaaaaaa-0000-4000-8000-000000000001','type','purchase','date','2026-01-16','amount','6000','currency','COP','fx_rate',null,'amount_cop','6000','installments_count',6,'interest_free',true,'rate_ea_applied','0.40','category_id',null,'merchant','Seis a tres','note','','installments',(select jsonb_agg(jsonb_build_object('number',n,'cutoff_date',(date '2026-02-15' + make_interval(months => n-1))::date,'principal',1000,'interest',0,'total',1000,'balance_after',6000-n*1000,'principal_cop',1000,'interest_cop',0,'total_cop',1000) order by n) from generate_series(1,6) n)));
select lives_ok($sql$select public.update_transaction_with_installments((select id from public.transactions where merchant='Seis a tres'),jsonb_build_object('card_id','aaaaaaaa-0000-4000-8000-000000000001','type','purchase','date','2026-01-16','amount','6000','currency','COP','fx_rate',null,'amount_cop','6000','installments_count',3,'interest_free',true,'rate_ea_applied','0.40','category_id',null,'merchant','Seis a tres','note','','installments',(select jsonb_agg(jsonb_build_object('number',n,'cutoff_date',(date '2026-02-15' + make_interval(months => n-1))::date,'principal',2000,'interest',0,'total',2000,'balance_after',6000-n*2000,'principal_cop',2000,'interest_cop',0,'total_cop',2000) order by n) from generate_series(1,3) n)))$sql$, 'cambia seis cuotas a tres');
select is((select count(*) from public.installments i join public.transactions t on t.id=i.transaction_id where t.merchant='Seis a tres'),3::bigint,'quedan exactamente tres cuotas');
select public.create_transaction_with_installments('{"card_id":"aaaaaaaa-0000-4000-8000-000000000001","type":"cash_advance","date":"2026-01-16","amount":"1000","currency":"COP","fx_rate":null,"amount_cop":"1000","installments_count":2,"interest_free":false,"rate_ea_applied":"0","category_id":null,"merchant":"Avance para borrar","note":"","installments":[{"number":1,"cutoff_date":"2026-02-15","principal":"500","interest":"0","total":"500","balance_after":"500","principal_cop":"500","interest_cop":"0","total_cop":"500"},{"number":2,"cutoff_date":"2026-03-15","principal":"500","interest":"0","total":"500","balance_after":"0","principal_cop":"500","interest_cop":"0","total_cop":"500"}]}'::jsonb);
select set_config('test.advance_id',(select id::text from public.transactions where merchant='Avance para borrar'),true);
delete from public.transactions where id=current_setting('test.advance_id')::uuid;
select is((select count(*) from public.transactions where parent_id=current_setting('test.advance_id')::uuid),0::bigint,'al borrar avance se borra la comisión');
select is((select count(*) from public.installments where transaction_id=current_setting('test.advance_id')::uuid),0::bigint,'al borrar avance se borran sus cuotas');
select set_config('test.transaction_id',(select id::text from public.transactions where merchant='Editado'),true);
select set_config('request.jwt.claims','{"sub":"bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb","role":"authenticated"}',true);
select throws_ok($sql$select public.update_transaction_with_installments(current_setting('test.transaction_id')::uuid,'{}'::jsonb)$sql$,'42501',null,'otro usuario no puede editar');
with deleted as (delete from public.transactions where id=current_setting('test.transaction_id')::uuid returning id)
select is((select count(*) from deleted),0::bigint,'otro usuario no puede borrar');
select * from finish();
rollback;
